import random

# States: 0=start, 1=middle, 2=goal
# Actions: 0=stay, 1=move forward
rewards  = {(0,1): 0, (1,1): 10, (0,0): -1, (1,0): -1}
transition = {(0,1):1, (1,1):2, (0,0):0, (1,0):1}
Q = {(s,a): 0.0 for s in [0,1] for a in [0,1]}
alpha, gamma, epsilon = 0.5, 0.9, 0.3

for episode in range(200):
    state = 0
    while state != 2:
        action = random.choice([0,1]) if random.random() < epsilon else max([0,1], key=lambda a: Q[(state,a)])
        next_state = transition.get((state,action), state)
        reward = rewards.get((state,action), 0)
        best_next = max(Q.get((next_state,a),0) for a in [0,1]) if next_state != 2 else 0
        Q[(state,action)] += alpha * (reward + gamma * best_next - Q[(state,action)])
        state = next_state

print('Learned Q-values:')
for key, val in Q.items():
    print(f'  Q{key} = {val:.2f}')

