import random
rewards={(0,1):0,(1,1):10,(0,0):-1,(1,0):-1}
transition={(0,1):1,(1,1):2,(0,0):0,(1,0):1}
Q={(s,a):0.0 for s in[0,1]for a in[0,1]}
alpha,gamma,eps=0.5,0.9,0.3
for _ in range(200):
    s=0
    while s!=2:
        a=random.choice([0,1])if random.random()<eps else max([0,1],key=lambda a:Q[(s,a)])
        ns=transition.get((s,a),s)
        r=rewards.get((s,a),0)
        bn=max(Q.get((ns,a),0)for a in[0,1])if ns!=2 else 0
        Q[(s,a)]+=alpha*(r+gamma*bn-Q[(s,a)])
        s=ns
print({k:round(v,2)for k,v in Q.items()})
